/** Exact native staging/Source rebasing/candidate causality and caller-preservation controls. */
final class ContextUniversalNativeCandidateMatrix {
    static int verified;
    static final class Fixture {
        final Mind mind;final Snapshot snapshot;
        Fixture(boolean x,String text)throws Exception{User u=new User();mind=new Mind(u);u.setCurrentMind(mind);if(!text.isEmpty())require(mind.compile(text,null,false),"actual candidate fixture compilation");ContextProductionInventory inventory=ContextProductionInventory.inspect(mind,UUID.randomUUID(),1,x,Collections.emptyList(),1000);ContextProductionNativeBinding.Result bound=ContextProductionNativeBinding.bind(mind,inventory,WORK,500000);require(bound.bound,bound.reason);snapshot=bound.snapshot;}
        void unchanged()throws Exception{ContextProductionInventory i=snapshot.inventory;require(i.fingerprint.equals(ContextProductionInventory.inspect(mind,i.context,i.revision,i.localX,i.initialization,1000).fingerprint),"caller native inventory unchanged by staging/evaluation/independent replay");}
    }
    static Policy policy(){return new Policy(ContextUniversalNativeBranchMatrix.policy(8,WORK,4096),1000,WORK,500000);}
    static Receipt stable(Result r,Snapshot base,List<Snapshot> cuts,String text,Policy p){require(r.status==Status.STABLE_SUPPLIED&&r.output!=null&&r.oppositions.isEmpty(),r.phase+": "+r.reason);Receipt receipt=r.output;ContextUniversalNativeCandidate.check(receipt,base,cuts,text,p,WORK,4096);++verified;require(receipt.artifact.base==base&&receipt.artifact.statement.equals(text)&&receipt.branch.x==receipt.artifact.staged&&receipt.branch.policy==p.branch,"exact requested candidate/actual staged native branch binding");require(receipt.originals.get(receipt.artifact.candidate).equals(receipt.artifact.candidate)&&receipt.originals.size()==receipt.artifact.staged.primary.size()+cuts.stream().mapToInt(s->s.primary.size()).sum(),"all original primary/foreign/candidate Sources accounted, candidate retained as NEW Source");return receipt;}
    static Set<Source> translated(Receipt r,Support support){Set<Source> out=new HashSet<>();for(Source source:support.sources){Source original=r.originals.get(source);require(original!=null,"every actual result Source mapped");out.add(original);}require(out.size()==support.sources.size(),"source translation remains injective");return out;}
    static void witnessRule(Receipt r,Fixture x,Fixture a,Fixture b,Fixture d){
        ContextProductionCandidate.Staged staged=r.artifact;Source oldSeed=x.snapshot.primary.get(0).source,newSeed=staged.rebased.get(oldSeed);require(!newSeed.equals(oldSeed)&&r.originals.get(newSeed).equals(oldSeed)&&newSeed.view.equals("inventory:"+staged.staged.inventory.fingerprint),"primary X Origin support uses authentic new view and translates to original seed Source");
        int count=0;for(Item item:r.branch.chain.trace.output.packet.items)if(item.atom.predicate.equals("s")){Origin origin=item.atom.arguments.get(0).origin;Source originalSeed=r.originals.get(origin.source);require(origin.binder==0&&(originalSeed.equals(oldSeed)||originalSeed.equals(a.snapshot.primary.get(0).source)),"actual staged X/private Origin identity; provenance translation does not replace Origin token");if(origin.source.localX)require(origin.source.equals(newSeed)&&!origin.source.equals(oldSeed),"proof Origin stays staged, not silently rewritten to old X");Set<Set<Source>> expected=new HashSet<>();for(Fixture donor:Arrays.asList(b,d))expected.add(ContextUniversalSourceAlternativesMatrix.sources(staged.candidate,originalSeed,donor.snapshot.primary.get(0).source,b.snapshot.primary.get(1).source,b.snapshot.primary.get(2).source));Set<Set<Source>> actual=new HashSet<>();for(Support support:item.proofs){require(support.depth==3&&support.sources.contains(staged.candidate),"actual candidate needed by every s3 proof");actual.add(translated(r,support));}require(actual.equals(expected)&&item.proofs.size()==2,"EXACT translated five-Source donor alternatives for actual X/private Origin");++count;}
        require(count==2&&r.branch.chain.trace.output.packet.items.size()==3,"only original X seed plus two candidate-dependent Origin s facts");
    }
    static void positive()throws Exception{
        Fixture x=new Fixture(true,"!$u seed(u,1); !@v all(v);"),a=new Fixture(false,"!$u seed(u,1);"),b=new Fixture(false,"!@u @v b(u,v); !@u @v r(u,v)&&need(v)->s(u,v); !need(2);"),d=new Fixture(false,"!@u @v b(u,v);");String rule="!@u @v seed(u,1)&&b(u,v)->r(u,v);";Policy p=policy();List<Snapshot> independent=Arrays.asList(a.snapshot,b.snapshot,d.snapshot);Receipt first=stable(ContextUniversalNativeCandidate.qualify(x.snapshot,independent,rule,p),x.snapshot,independent,rule,p);witnessRule(first,x,a,b,d);
        Snapshot group=ContextProductionNativeBinding.trusted("candidate-native",Arrays.asList(d.snapshot,b.snapshot),WORK);List<Snapshot> trusted=Arrays.asList(group,a.snapshot);Receipt second=stable(ContextUniversalNativeCandidate.qualify(x.snapshot,trusted,rule,p),x.snapshot,trusted,rule,p);witnessRule(second,x,a,b,d);require(!first.artifact.candidate.equals(second.artifact.candidate)&&first.artifact.base==second.artifact.base,"separate trial candidate identities/views never collapse across equivalent rule text");
        Fixture anchor=new Fixture(true,"!anchor(1);"),consumer=new Fixture(false,"!@u seed(u,1)->ready(u,1);");String existential="!$u seed(u,1);";List<Snapshot> one=Collections.singletonList(consumer.snapshot);Receipt created=stable(ContextUniversalNativeCandidate.qualify(anchor.snapshot,one,existential,p),anchor.snapshot,one,existential,p);Item ready=created.branch.chain.trace.output.packet.items.stream().filter(i->i.atom.predicate.equals("ready")).findFirst().get();require(ready.atom.arguments.get(0).origin.source.equals(created.artifact.candidate)&&ready.atom.arguments.get(0).origin.binder==0,"new candidate existential Origin is candidate-owned, not rebased old anchor");require(ready.proofs.size()==1&&ready.proofs.get(0).depth==1&&translated(created,ready.proofs.get(0)).equals(ContextUniversalSourceAlternativesMatrix.sources(created.artifact.candidate,consumer.snapshot.primary.get(0).source)),"exact candidate witness +consumer original Source result1");
        Fixture yes=new Fixture(false,"!p(1);"),no=new Fixture(false,"!~p(1);");String extra="!extra(2);";List<Snapshot> siblings=Arrays.asList(yes.snapshot,no.snapshot);Receipt unrelated=stable(ContextUniversalNativeCandidate.qualify(anchor.snapshot,siblings,extra,p),anchor.snapshot,siblings,extra,p);require(unrelated.branch.chain.trace.output.packet.items.size()==2&&!ContextUniversalGroupedRoundsRunner.has(unrelated.branch.chain.trace.output.packet,"p"),"irrelevant candidate does not communalize contradictory sibling opinions");
        for(Fixture f:Arrays.asList(x,a,b,d,anchor,consumer,yes,no))f.unchanged();require(verified==4,"four independent native candidate receipt replays");System.out.println("NATIVE_CANDIDATE_POSITIVE trials=4 independentAndTrusted=true originalOriginsTranslated=true candidateExistential=true nativeCallersUnchanged=true");
    }
    static void no(Result r,String why){require(r.status==Status.INCOMPLETE&&r.output==null&&r.oppositions.isEmpty(),why+": "+r.status+"/"+r.phase+": "+r.reason);}
    static void rejected(Result r,boolean usesCandidate,int round,Set<Source> fixed){require(r.status==Status.REFUTED&&r.output==null&&!r.oppositions.isEmpty(),r.phase+": "+r.reason);for(List<Attribution> values:r.oppositions.values())for(Attribution a:values){require(a.usesCandidate==usesCandidate&&a.proof.clause==null&&a.proof.support.depth==(round==0?1:2)&&a.rejection.round==round,"exact causal tag/actual empty grade/initial versus grouped round");Set<Source> expected=new HashSet<>(fixed);if(usesCandidate)expected.add(a.candidate);require(a.originalSources.equals(expected)&&a.proof.support.sources.contains(a.candidate)==usesCandidate,"candidate original-Source attribution does not infer causality from mere presence in trial");}}
    static void refusals()throws Exception{
        Fixture x=new Fixture(true,"!anchor(1); !@u p(u);"),donor=new Fixture(false,"!b(1);"),opposite=new Fixture(false,"!~r(1);");String rule="!@u p(u)&&b(u)->r(u);";Policy p=policy();List<Snapshot> cuts=Arrays.asList(donor.snapshot,opposite.snapshot);Result delayed=ContextUniversalNativeCandidate.qualify(x.snapshot,cuts,rule,p);rejected(delayed,true,1,ContextUniversalSourceAlternativesMatrix.sources(x.snapshot.primary.get(1).source,donor.snapshot.primary.get(0).source,opposite.snapshot.primary.get(0).source));require(delayed.oppositions.keySet().equals(new HashSet<>(Arrays.asList(Cut.of(donor.snapshot),Cut.of(opposite.snapshot)))) ,"both subsequent rejecting cuts retained");for(List<Attribution> values:delayed.oppositions.values())for(Attribution a:values)require(!a.proof.support.sources.contains(x.snapshot.primary.get(1).source)&&a.originalSources.contains(x.snapshot.primary.get(1).source),"original X Source is translated from rebased trial proof, not assumed unchanged");
        Fixture anchor=new Fixture(true,"!anchor(1);"),positive=new Fixture(false,"!p(1);"),negative=new Fixture(false,"!~p(1);");rejected(ContextUniversalNativeCandidate.qualify(anchor.snapshot,Collections.singletonList(positive.snapshot),"!~p(1);",p),true,0,ContextUniversalSourceAlternativesMatrix.sources(positive.snapshot.primary.get(0).source));Snapshot group=ContextProductionNativeBinding.trusted("candidate-irrelevant-refutation",Arrays.asList(positive.snapshot,negative.snapshot),WORK);Result preexisting=ContextUniversalNativeCandidate.qualify(anchor.snapshot,Collections.singletonList(group),"!extra(2);",p);rejected(preexisting,false,0,ContextUniversalSourceAlternativesMatrix.sources(positive.snapshot.primary.get(0).source,negative.snapshot.primary.get(0).source));
        for(String text:Arrays.asList("?p(1);","!a(1); !b(1);","!anchor(1);","!left(1)||right(1);"))no(ContextUniversalNativeCandidate.qualify(anchor.snapshot,Collections.emptyList(),text,p),"query/script/duplicate/unsupported declaration never yields candidate approval");
        no(ContextUniversalNativeCandidate.qualify(anchor.snapshot,Collections.emptyList(),"!extra(2);",new Policy(p.branch,1000,1,500000)),"preparation work stop");Policy oneEvent=new Policy(p.branch,1000,WORK,1);stable(ContextUniversalNativeCandidate.qualify(anchor.snapshot,Collections.emptyList(),"!extra(2);",oneEvent),anchor.snapshot,Collections.emptyList(),"!extra(2);",oneEvent);boolean invalidEvents=false;try{new Policy(p.branch,1000,WORK,0);}catch(IllegalArgumentException expected){invalidEvents=true;}require(invalidEvents,"positive per-capture event limit required; event1 suffices for a simple input");no(ContextUniversalNativeCandidate.qualify(anchor.snapshot,Collections.emptyList(),"!extra(2);",new Policy(p.branch,1,WORK,500000)),"whole candidate row cap");no(ContextUniversalNativeCandidate.qualify(anchor.snapshot,Collections.emptyList(),"!extra(2);",new Policy(ContextUniversalNativeBranchMatrix.policy(8,1,4096),1000,WORK,500000)),"candidate Source-binding work stop, no prepared prefix");
        receiptBoundaries(anchor,p);for(Fixture f:Arrays.asList(x,donor,opposite,anchor,positive,negative))f.unchanged();System.out.println("NATIVE_CANDIDATE_REFUSALS candidateDependentAndIndependent=true exactRebasedAttribution=true semanticRequestReplay=true preparationStopsAtomic=true");
    }
    static void fails(Receipt r,Snapshot base,List<Snapshot> cuts,String text,Policy p,int work,String why){boolean failed=false;try{ContextUniversalNativeCandidate.check(r,base,cuts,text,p,work,4096);}catch(IllegalStateException|IllegalArgumentException expected){failed=true;}require(failed,why);}
    static void mutate(Receipt r,Object object,String name,Object value,Snapshot base,List<Snapshot> cuts,String text,Policy p)throws Exception{Field field=object.getClass().getDeclaredField(name);field.setAccessible(true);Object old=field.get(object);field.set(object,value);try{fails(r,base,cuts,text,p,WORK,"fresh exact candidate check refuses altered "+name);}finally{field.set(object,old);}}
    static void receiptBoundaries(Fixture x,Policy p)throws Exception{
        List<Snapshot> cuts=Collections.emptyList();String text="!extra(2);";Receipt r=stable(ContextUniversalNativeCandidate.qualify(x.snapshot,cuts,text,p),x.snapshot,cuts,text,p);Receipt other=stable(ContextUniversalNativeCandidate.qualify(x.snapshot,cuts,text,p),x.snapshot,cuts,text,p);fails(r,x.snapshot,cuts,"!extra(3);",p,WORK,"different requested assertion");fails(r,new Fixture(true,"!anchor(1);").snapshot,cuts,text,p,WORK,"equal-data different native base");fails(r,x.snapshot,cuts,text,policy(),WORK,"actual candidate policy identity");fails(r,x.snapshot,cuts,text,p,1,"independent verification work stop");
        mutate(r,r.artifact,"rebased",Collections.emptyMap(),x.snapshot,cuts,text,p);mutate(r,r.artifact,"candidate",r.artifact.rebased.values().iterator().next(),x.snapshot,cuts,text,p);mutate(r,r.artifact,"identity",UUID.randomUUID(),x.snapshot,cuts,text,p);mutate(r,r,"originals",Collections.singletonMap(r.artifact.candidate,r.artifact.candidate),x.snapshot,cuts,text,p);mutate(r,r,"branch",other.branch,x.snapshot,cuts,text,p);
        // Metadata AND caller assertion agree with the forgery; fresh native replay must still reject.
        mutate(r,r.artifact,"statement","!harmless(9);",x.snapshot,cuts,"!harmless(9);",p);ContextUniversalNativeCandidate.check(r,x.snapshot,cuts,text,p,WORK,4096);boolean immutable=false;try{r.originals.clear();}catch(UnsupportedOperationException expected){immutable=true;}require(immutable,"original Source translation immutable");
    }
}
